function OnGlobalLoad() {
    //console.log('Page Loaded');
    const BASE_WIDTH = 1920;
    const BASE_HEIGHT = 1080;

    function fitPage() {
        // Kira skala berasingan untuk lebar (X) dan tinggi (Y)
        const scaleX = window.innerWidth / BASE_WIDTH;
        const scaleY = window.innerHeight / BASE_HEIGHT;

        // Set saiz asas & aplikasikan scaling mengikut lebar dan tinggi skrin
        document.body.style.width = BASE_WIDTH + "px";
        document.body.style.height = BASE_HEIGHT + "px";
        document.body.style.transform = "scale(" + scaleX + ", " + scaleY + ")";
        document.body.style.transformOrigin = "top left";

        // Memastikan tiada scrollbar muncul
        document.body.style.overflow = "hidden";
        document.body.style.margin = "0";
        document.body.style.padding = "0";
    }

    // Jalankan semasa page mula muat dan bila saiz window diubah
    window.addEventListener("resize", fitPage);
    fitPage();
}


function OnGlobalPeriodic() {
    //console.log('Global Code Executing');
}

function OnGlobalExit() {
    //console.log('Global Exited');
}
